const sitePages = new Set(["/","/index.html","/ecosystem.html","/network.html","/manifesto.html","/roadmap.html","/docs.html","/connect.html","/connect-soon.html","/wallet.html","/identity.html","/chain.html","/scan.html","/terms.html","/privacy.html","/tokenomics.html","/airdrop.html"]);

// Keep bookmarks shared from the earlier homepage working after the split.
const legacyPages={
  "#ecosystem": "ecosystem.html",
  "#network-services": "network.html",
  "#manifesto": "manifesto.html",
  "#roadmap": "roadmap.html",
  "#download": "connect.html#soon",
  "#connect-features": "connect.html#connect-features",
  "#technology": "network.html#technology"
};
if(document.body.dataset.page==='index' && legacyPages[window.location.hash]) {
  const destination=new URL(legacyPages[window.location.hash],window.location.href);
  destination.search=window.location.search;
  window.location.replace(destination.href);
}

const translatedElements = [...document.querySelectorAll('[data-i18n]')];
const english = new Map(translatedElements.map(element=>[element,element.innerHTML]));
const languageToggle = document.querySelector('.language-toggle');
const menuToggle = document.querySelector('.menu-toggle');
const navigation = document.querySelector('#main-nav');
// Header link groups are disclosure buttons; aria-expanded is their only open state.
const navGroups = [...document.querySelectorAll('.nav-group')];
const desktopNav = window.matchMedia('(min-width:1101px)');
const motionButton = document.querySelector('.motion-toggle');
const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
let language = 'en';
let motionPaused = false;

function updateMotionLabel() {
  if (!motionButton) return;
  const off=motionPaused || reducedMotion.matches;
  motionButton.disabled=reducedMotion.matches;
  motionButton.setAttribute('aria-pressed',String(off));
  motionButton.setAttribute('aria-label',reducedMotion.matches ? (language==='tr'?'Azaltılmış hareket tercihi etkin':'Reduced motion preference enabled') : (language==='tr'?(off?'Animasyonu sürdür':'Animasyonu duraklat'):(off?'Resume animation':'Pause animation')));
  motionButton.firstElementChild.textContent=off?'▷':'Ⅱ';
}

function setGroup(group,open) {
  group.querySelector('.nav-group-toggle').setAttribute('aria-expanded',String(open));
}

function closeGroups(except) {
  navGroups.forEach(group=>{if(group!==except)setGroup(group,false);});
}

function setMenu(open) {
  if (!open) closeGroups();
  if (!menuToggle || !navigation) return;
  menuToggle.setAttribute('aria-expanded',String(open));
  menuToggle.setAttribute('aria-label',language==='tr'?(open?'Menüyü kapat':'Menüyü aç'):(open?'Close menu':'Open menu'));
  navigation.classList.toggle('open',open);
}

function setLanguage(next) {
  language=next==='tr'?'tr':'en';
  document.documentElement.lang=language;
  translatedElements.forEach(element=>{
    const key=element.dataset.i18n;
    // Both dictionaries are authored with the page. No user input is rendered as HTML.
    element.innerHTML=language==='tr'?(turkish[key]??english.get(element)):english.get(element);
  });
  languageToggle.firstChild.textContent=language.toUpperCase()+' ';
  languageToggle.setAttribute('aria-label',language==='en'?'Switch to Turkish':'İngilizceye geç');
  document.querySelectorAll('.wordmark').forEach(link=>link.setAttribute('aria-label',language==='tr'?'Nodus ana sayfa':'Nodus home'));
  document.querySelectorAll('a[href]').forEach(link=>{
    if(link.getAttribute('href').startsWith('#'))return;
    const url=new URL(link.getAttribute('href'),window.location.href);
    const nodusOrigin=['https://nodusnetwork.io','https://wiki.nodusnetwork.io','https://scan.nodusnetwork.io'].includes(url.origin);
    const localPage=url.origin===window.location.origin && (sitePages.has(url.pathname) || /^\/(wiki|scan)\//.test(url.pathname));
    if(!nodusOrigin && !localPage)return;
    url.searchParams.set('lang',language);
    link.setAttribute('href',url.origin===window.location.origin?`${url.pathname}${url.search}${url.hash}`:url.href);
  });
  if(navigation)navigation.setAttribute('aria-label',language==='tr'?'Ana gezinme':'Main navigation');
  const filters=document.querySelector('.roadmap-filters');
  if(filters)filters.setAttribute('aria-label',language==='tr'?'Yol haritasını filtrele':'Filter roadmap');
  const sidebar=document.querySelector('.docs-sidebar');
  if(sidebar)sidebar.setAttribute('aria-label',language==='tr'?'Bu sayfada':'On this page');
  const art=document.querySelector('.hero-art');
  if(art)art.setAttribute('aria-label',language==='tr'?'Soyut, örgü biçiminde bir ağ heykeli':'An abstract woven network sculpture');
  const scroll=document.querySelector('.hero-bottom>a');
  if(scroll)scroll.setAttribute('aria-label',language==='tr'?'Nodus’u keşfet':'Explore Nodus');
  const principleSection=document.querySelector('.principles');
  if(principleSection)principleSection.setAttribute('aria-label',language==='tr'?'Nodus ilkeleri':'Nodus principles');
  document.title=language==='tr'?document.body.dataset.titleTr:document.body.dataset.titleEn;
  setMenu(false);
  updateMotionLabel();
  const currentUrl=new URL(window.location.href);
  currentUrl.searchParams.set('lang',language);
  history.replaceState(null,'',currentUrl);
  try { localStorage.setItem('nodus-language',language); } catch { /* Language still works when storage is blocked. */ }
}

let initialLanguage=new URLSearchParams(window.location.search).get('lang');
if(!initialLanguage){try{initialLanguage=localStorage.getItem('nodus-language');}catch{/* English is the default. */}}
setLanguage(initialLanguage);
languageToggle.addEventListener('click',()=>setLanguage(language==='en'?'tr':'en'));
menuToggle?.addEventListener('click',()=>setMenu(menuToggle.getAttribute('aria-expanded')!=='true'));
navigation?.addEventListener('click',event=>{if(event.target.closest('a'))setMenu(false);});
document.addEventListener('keydown',event=>{
  if(event.key!=='Escape')return;
  const openGroup=navGroups.find(group=>group.querySelector('.nav-group-toggle').getAttribute('aria-expanded')==='true');
  if(openGroup){setGroup(openGroup,false);openGroup.querySelector('.nav-group-toggle').focus();return;}
  if(menuToggle?.getAttribute('aria-expanded')==='true'){setMenu(false);menuToggle.focus();}
});
document.addEventListener('click',event=>{
  if(!event.target.closest('.site-header'))setMenu(false);
  else if(!event.target.closest('.main-nav'))closeGroups();
});
desktopNav.addEventListener('change',()=>setMenu(false));

// Without this class, CSS opens the groups on hover and focus so the links work without JavaScript.
navigation?.classList.add('nav-ready');
navGroups.forEach(group=>{
  const toggle=group.querySelector('.nav-group-toggle');
  // A desktop mouse opens the group on hover, so its click never closes it; keyboard and touch toggle.
  const hoverMode=event=>event.pointerType==='mouse' && desktopNav.matches;
  toggle.addEventListener('click',event=>{
    const open=hoverMode(event) || toggle.getAttribute('aria-expanded')!=='true';
    closeGroups(group);
    setGroup(group,open);
  });
  group.addEventListener('pointerenter',event=>{if(hoverMode(event)){closeGroups(group);setGroup(group,true);}});
  group.addEventListener('pointerleave',event=>{if(hoverMode(event))setGroup(group,false);});
  group.addEventListener('focusout',event=>{if(event.relatedTarget && !group.contains(event.relatedTarget))setGroup(group,false);});
});

document.querySelectorAll('.faq-list details').forEach(detail=>detail.addEventListener('toggle',()=>{
  if(detail.open)document.querySelectorAll('.faq-list details').forEach(other=>{if(other!==detail)other.open=false;});
}));

const canvas=document.querySelector('#network-art');
if(canvas){
  const art=createNetworkArt(canvas);
  motionButton.addEventListener('click',()=>{motionPaused=!motionPaused;art.setPaused(motionPaused);updateMotionLabel();});
  reducedMotion.addEventListener('change',updateMotionLabel);
}


// Roadmap filters keep the selected category when the page language changes.
document.querySelectorAll('[data-roadmap-filter]').forEach(button => {
  button.addEventListener('click', () => {
    const selected = button.dataset.roadmapFilter;
    document.querySelectorAll('[data-roadmap-filter]').forEach(filter => {
      filter.setAttribute('aria-pressed', String(filter === button));
    });
    document.querySelectorAll('[data-milestone-status]').forEach(item => {
      item.hidden = selected !== 'all' && item.dataset.milestoneStatus !== selected;
    });
  });
});
